CREATE TABLE IF NOT EXISTS system_growth_channels (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,type TEXT,status TEXT DEFAULT 'active',metadata JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS system_growth_funnel_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,channel_id UUID,stage TEXT NOT NULL,entity_id UUID,value NUMERIC(18,2),payload JSONB NOT NULL DEFAULT '{}'::jsonb,occurred_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS system_growth_experiments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,status TEXT DEFAULT 'draft',hypothesis TEXT,baseline JSONB NOT NULL DEFAULT '{}'::jsonb,variants JSONB NOT NULL DEFAULT '[]'::jsonb,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS system_growth_opportunities (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,source_domain TEXT,score NUMERIC(7,2),status TEXT DEFAULT 'candidate',detail JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_growth_channel_user ON system_growth_channels(user_id,status);
CREATE INDEX IF NOT EXISTS idx_growth_funnel_user ON system_growth_funnel_events(user_id,occurred_at DESC);